using namespace std;

struct TreeNode {
    long long val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(long long v) : val(v), left(nullptr), right(nullptr) {}
};

// Builds a binary tree from a level-order list of words; "N" marks a missing child.
TreeNode* buildTree(const vector<string>& vals) {
    if (vals.empty() || vals[0] == "N") return nullptr;
    TreeNode* root = new TreeNode(stoll(vals[0]));
    vector<TreeNode*> queue = {root};
    size_t head = 0, i = 1;
    while (head < queue.size() && i < vals.size()) {
        TreeNode* node = queue[head++];
        if (vals[i] != "N") {
            node->left = new TreeNode(stoll(vals[i]));
            queue.push_back(node->left);
        }
        i++;
        if (i < vals.size() && vals[i] != "N") {
            node->right = new TreeNode(stoll(vals[i]));
            queue.push_back(node->right);
        }
        i++;
    }
    return root;
}

// Prints a tree in the same level-order form ("empty" for no tree).
void printTree(TreeNode* root) {
    if (root == nullptr) {
        cout << "empty\n";
        return;
    }
    vector<string> out;
    vector<TreeNode*> queue = {root};
    size_t head = 0;
    while (head < queue.size()) {
        TreeNode* node = queue[head++];
        if (node == nullptr) {
            out.push_back("N");
        } else {
            out.push_back(to_string(node->val));
            queue.push_back(node->left);
            queue.push_back(node->right);
        }
    }
    while (!out.empty() && out.back() == "N") out.pop_back();
    for (size_t k = 0; k < out.size(); k++) cout << (k ? " " : "") << out[k];
    cout << "\n";
}


pair<long long, long long> rob(TreeNode* root) {
    // Your code here: return {best if the root is taken, best if the root is skipped}
    return {0, 0};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long t;
    cin >> t;
    vector<string> vals(t);
    for (int i = 0; i < t; i++) cin >> vals[i];

    pair<long long, long long> best = rob(buildTree(vals));
    cout << max(best.first, best.second) << "\n";

    return 0;
}

